SELECT channel, CASE WHEN amount >= 1490 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, APPROX_PERCENTILE(discount, 0.95) AS discount_p95, SUM(CASE WHEN channel = 'partner' THEN amount ELSE 0 END) AS partner_amount, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END), 0), 2) AS discount_per_cancelled, AVG(discount) FILTER (WHERE channel = 'partner') AS partner_avg_discount, COUNT(DISTINCT status) AS distinct_status, GROUPING_ID() AS grouping_id FROM orders GROUP BY GROUPING SETS ((channel, CASE WHEN amount >= 1490 THEN 'PREMIUM' ELSE 'STANDARD' END), (channel)) ORDER BY channel DESC NULLS FIRST;
